#include <iostream>

int main() {
    int score{72};

    if (score >= 90) {
        std::cout << "A\n";
    } else if (score >= 70) {
        std::cout << "B\n";
    } else {
        std::cout << "C or below\n";
    }

    if (int remainder = score % 10; remainder == 0) {
        std::cout << "round number\n";
    } else {
        std::cout << "remainder " << remainder << '\n';
    }
}

#include <iostream>

int main() {
    char op{'*'};
    int a{6};
    int b{7};

    switch (op) {
        case '+':
            std::cout << a + b << '\n';
            break;
        case '*':
            std::cout << a * b << '\n';
            break;
        case '/':
            if (b == 0) {
                std::cout << "cannot divide by zero\n";
                break;
            }
            std::cout << a / b << '\n';
            break;
        default:
            std::cout << "unknown operator\n";
    }
}

#include <iostream>
#include <vector>

int main() {
    for (int i = 1; i <= 15; ++i) {
        if (i % 15 == 0) {
            std::cout << "FizzBuzz";
        } else if (i % 3 == 0) {
            std::cout << "Fizz";
        } else if (i % 5 == 0) {
            std::cout << "Buzz";
        } else {
            std::cout << i;
        }
        std::cout << (i < 15 ? ' ' : '\n');
    }

    std::vector<int> temperatures{21, 25, 19, 30};
    int sum{};
    for (int t : temperatures) {
        sum += t;
    }
    std::cout << "average: " << static_cast<double>(sum) / temperatures.size() << '\n';
}

#include <iostream>

int main() {
    int n{27};
    int steps{};
    while (n != 1) {
        n = (n % 2 == 0) ? n / 2 : 3 * n + 1;
        ++steps;
    }
    std::cout << "27 reaches 1 in " << steps << " steps\n";

    for (int i = 0; i < 10; ++i) {
        if (i % 2 == 0) continue;   // skip even numbers
        if (i > 7) break;           // stop after 7
        std::cout << i << '\n';
    }

    int attempts{};
    do {
        ++attempts;
    } while (attempts < 3);
    std::cout << "attempts: " << attempts << '\n';
}

